// from the reference executable (jsonschema 4.23.0).
//
// Observed behavior (verified by probing):
//   - The $schema URI is normalized with urllib.parse.urlsplit-like
//     semantics: \t \n \r are removed anywhere, leading C0-control/space
//     characters are stripped, the scheme is lowercased, an empty query
//     ("...?") or empty fragment ("...#") is dropped, and the result is
//     compared against the canonical meta-schema URIs (host and path are
//     case-sensitive, non-empty query/fragment prevents a match).
//   - Canonical URIs (after normalization, i.e. without the legacy "#"):
//       http://json-schema.org/draft-04/schema   -> Draft4Validator
//       http://json-schema.org/draft-06/schema   -> Draft6Validator
//       http://json-schema.org/draft-07/schema   -> Draft7Validator
//       https://json-schema.org/draft/2019-09/schema -> Draft201909Validator
//       https://json-schema.org/draft/2020-12/schema -> Draft202012Validator
//   - Missing or unrecognized $schema -> the latest draft (Draft202012Validator).
//   - A non-string $schema crashes the reference program (empty stdout,
//     non-zero exit), so we throw.

const META_SCHEMA_NAMES = {
  'http://json-schema.org/draft-04/schema': 'Draft4Validator',
  'http://json-schema.org/draft-06/schema': 'Draft6Validator',
  'http://json-schema.org/draft-07/schema': 'Draft7Validator',
  'https://json-schema.org/draft/2019-09/schema': 'Draft201909Validator',
  'https://json-schema.org/draft/2020-12/schema': 'Draft202012Validator',
};

const LATEST_NAME = 'Draft202012Validator';

// Mimics urllib.parse.urlsplit + urlunsplit closely enough for URI lookup:
// remove \t \n \r everywhere, strip leading C0 control/space, lowercase the
// scheme, drop empty query/fragment.
function normalizeUri(uri) {
  let rest = uri.replace(/[\t\n\r]/g, '').replace(/^[\x00-\x20]+/, '');

  let fragment = '';
  const hashIndex = rest.indexOf('#');
  if (hashIndex !== -1) {
    fragment = rest.slice(hashIndex + 1);
    rest = rest.slice(0, hashIndex);
  }

  let query = '';
  const queryIndex = rest.indexOf('?');
  if (queryIndex !== -1) {
    query = rest.slice(queryIndex + 1);
    rest = rest.slice(0, queryIndex);
  }

  const schemeMatch = rest.match(/^([A-Za-z][A-Za-z0-9+.-]*):/);
  if (schemeMatch) {
    rest = schemeMatch[1].toLowerCase() + rest.slice(schemeMatch[1].length);
  }

  let normalized = rest;
  if (query) normalized += '?' + query;
  if (fragment) normalized += '#' + fragment;
  return normalized;
}

export function validatorForName(schema) {
  if (schema === true || schema === false) {
    return LATEST_NAME;
  }
  if (schema === null || typeof schema !== 'object') {
    // Unreachable in the reference program (validation crashes first on a
    // non-object schema), but Python raises here, so we do too.
    throw new TypeError('validator_for: schema must be a JSON object or boolean');
  }
  if (Array.isArray(schema)) {
    // Python: "$schema" not in <list> is simply True -> default validator.
    // (Also unreachable in practice: validation crashes first.)
    return LATEST_NAME;
  }
  if (!('$schema' in schema)) {
    return LATEST_NAME;
  }
  const uri = schema['$schema'];
  if (typeof uri !== 'string') {
    // The reference program crashes on non-string $schema values.
    throw new TypeError('validator_for: $schema must be a string');
  }
  return META_SCHEMA_NAMES[normalizeUri(uri)] ?? LATEST_NAME;
}

