// Whether the token following an option should be consumed as its value,
// mirroring argparse._parse_optional / _get_values.
function looksLikeValue(token) {
  if (!token.startsWith('-')) return true;
  if (token === '-') return true;
  if (NEGATIVE_NUMBER.test(token)) return true;
  if (token.includes(' ')) return true;
  return false;
}

