      const name = eqIndex === -1 ? arg : arg.slice(0, eqIndex);
      const inlineValue = eqIndex === -1 ? null : arg.slice(eqIndex + 1);
      const option = resolveLongOption(name);

      if (option === null) {
        extras.push(arg);
